contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 time) public payable {
        require(amount >= 10 ether);
        require(address(this).balance >= 10 ether);

        uint256 before = c.pastBlockTime();
        require(before < time);

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterVal = c.pastBlockTime();
            assert(afterVal > before && afterVal > block.timestamp);
        } else {
            assert(c.pastBlockTime() == before);
        }
    }

    receive() external payable {}
}

