            try c.fallback{value: 10 ether}() { reverted2 = false; } catch { reverted2 = true; }
        } else {
            reverted2 = true;
        }

        uint256 pastAfterSecond = c.pastBlockTime();

        // General rule: only one fallback call can succeed for a given timestamp.
        assert(reverted1 || reverted2 || pastAfterSecond == t2 + 1);
    }

    receive() external payable {}
}

