            assert(c.pastBlockTime() == beforePast);
        } else {
            assert(c.pastBlockTime() == t + 1);
            assert(c.pastBlockTime() > t);
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
                assert(address(this).balance == beforeBal + 10 ether);
            } else {
                assert(address(c).balance == beforeBal + 10 ether);
            }
        }
    }
}

