        uint oldPastBlockTime = c.pastBlockTime();

        // Create a state where the next fallback call is valid: store a past time
        // strictly less than the current timestamp. A single 10 ether call is the
        // only state-changing call on c.
        uint balBefore = address(c).balance;
        uint balThisBefore = address(this).balance;

