        assert(
            reverted == (block.number % 15 != 0) || false
        );

        assert(
            !reverted
                ? (newPastBlockTime == block.timestamp + 1)
                : (newPastBlockTime == oldPastBlockTime)
        );

        assert(
            !reverted
                ? (
                    block.number % 15 == 0
                        ? (balAfter == balBefore + amount - (balBefore + amount) && balThisAfter == balThisBefore + (balBefore + amount))
                        : (balAfter == balBefore + amount && balThisAfter == balThisBefore)
                )
                : (balAfter == balBefore && balThisAfter == balThisBefore)
        );
    }

    receive() external payable {}
}

