    constructor(C _c) {
        c = _c;
    }

    function run(bool attemptAdvance) public payable {
        require(address(this).balance >= 10 ether);

        uint beforeTime = c.pastBlockTime();
        uint beforeBal = address(c).balance;

        bool reverted;
        uint expectedNewTime;

        if (attemptAdvance) {
            // ensure the timestamp strictly increases relative to the stored pastBlockTime
            while (block.timestamp <= beforeTime) {}
            expectedNewTime = block.timestamp + 1;
            try c.call{value: 10 ether}("") {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // make the timestamp non-increasing by using a past timestamp via block manipulation is not possible;
            // instead, perform a successful call first to set pastBlockTime ahead, then attempt an immediate second call.
            // Since we cannot change block.timestamp within one tx, we use the fact that after a successful call
            // pastBlockTime = block.timestamp + 1, so the next call in the same block will revert.
            // First, do a successful call if possible.
            while (block.timestamp <= beforeTime) {}
            try c.call{value: 10 ether}("") {
                // first call succeeded
            } catch {
                // unexpected revert, but we still proceed
            }
            beforeTime = c.pastBlockTime();
            beforeBal = address(c).balance;
            try c.call{value: 10 ether}("") {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        if (attemptAdvance) {
            assert(!reverted && c.pastBlockTime() == expectedNewTime && address(c).balance == beforeBal + 10 ether);
        } else {
            assert(reverted && c.pastBlockTime() == beforeTime && address(c).balance == beforeBal);
        }
    }

    receive() external payable {}
}

