        uint pastBlockTimeAfter = c.pastBlockTime();
        uint cBalAfter = address(c).balance;
        uint myBalAfter = address(this).balance;

        // General rule: the deciding call either reverts (value must be exactly 10 ether, so
        // amount != 10 ether necessarily reverts, and a stale timestamp window can also revert),
        // or it succeeds and then pastBlockTime was strictly advanced past its previous value
        // while c's balance change is fully explained by the 10-ether input and the conditional sweep.
        if (!decidingReverted) {
            assert(amount == 10 ether);
            assert(pastBlockTimeAfter > pastBlockTimeBefore2);
            // If the contract did not sweep, it gained exactly 10 ether from this call.
            // If it swept (block.number % 15 == 0), it sent its whole prior balance plus the
            // 10 ether back, so its balance is exactly the 10 ether received in this very call.
            assert(cBalAfter == cBalBefore2 + 10 ether || cBalAfter == 10 ether);
        } else {
            // A revert must not have changed the observable balance or timer.
            assert(cBalAfter == cBalBefore2);
            assert(pastBlockTimeAfter == pastBlockTimeBefore2);
            assert(myBalAfter == myBalBefore2);
        }
    }

    receive() external payable {}
}

