contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 dt) public payable {
        // amount must be exactly 10 ether to exercise the fallback's value requirement
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Advance the block timestamp into the future relative to the current chain time.
        // This makes the precondition block.timestamp > pastBlockTime satisfiable when dt > 0.
        // When dt == 0, the timestamp remains 0; combined with an initial pastBlockTime of 0,
        // the strict inequality fails and the fallback should revert.
        uint256 target = block.timestamp + dt;
        assembly {
            pop(chainid())
        }
        // We cannot set block.timestamp directly without cheatcodes, so we rely on the
        // checker running the transaction at a timestamp that makes this meaningful.
        // Use the read value of pastBlockTime to decide expectation.

        uint256 prev = c.pastBlockTime();
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 nowTs = block.timestamp;
        if (!reverted) {
            // On success, the fallback must have required nowTs > prev
            // and stored nowTs + 1 as the new pastBlockTime.
            assert(nowTs > prev && c.pastBlockTime() == nowTs + 1);
        } else {
            // On revert, the stored pastBlockTime must remain unchanged.
            assert(c.pastBlockTime() == prev);
        }
    }

    receive() external payable {}
}

